const songTab=document.createElement('button');songTab.setAttribute('role','tab');songTab.id='topic-6';songTab.dataset.topic='6';songTab.setAttribute('aria-controls','panel-6');songTab.textContent='06 / 弹唱演示';$('.workspace-tabs').append(songTab);
const songPanel=document.createElement('article');songPanel.id='panel-6';songPanel.className='topic-panel';songPanel.setAttribute('role','tabpanel');songPanel.setAttribute('aria-labelledby','topic-6');songPanel.hidden=true;$('.learning-workspace').append(songPanel);
const priorTopic=switchTopic;switchTopic=function(i,hash=true){if(i!==6){priorTopic(i,hash);return}$$('[role=tabpanel]').forEach(p=>p.hidden=p!==songPanel);$$('[data-topic]').forEach(b=>{b.setAttribute('aria-selected',b===songTab);b.tabIndex=b===songTab?0:-1});if(hash)history.replaceState(null,'','#topic-6');scrollTo({top:0,behavior:'instant'})};songTab.onclick=()=>switchTopic(6);$$('[data-topic]').forEach(b=>b.onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();let i=+b.dataset.topic;i=e.key==='Home'?0:e.key==='End'?6:(i+(e.key==='ArrowRight'?1:6))%7;switchTopic(i);$('#topic-'+i).focus()}});
const n=(degree,beats=1,octave=0)=>({degree,beats,octave});
const originalScore={title:'微光归途',credit:'本站原创教学短曲 · 4/4 拍',sections:[
{name:'前奏',type:'instrumental',bars:[{chord:'I',melody:[n(1),n(3),n(5),n(1,1,1)]},{chord:'V',melody:[n(7),n(5),n(2),n(5)]}]},
{name:'演唱 A',type:'vocal',bars:[{chord:'I',lyric:'让声音，慢慢亮起',melody:[n(3),n(3),n(5),n(6)]},{chord:'vi',lyric:'沿着光，走过四季',melody:[n(6),n(5),n(3),n(1)]},{chord:'IV',lyric:'一颗音，落在掌心',melody:[n(4),n(6),n(1,1,1),n(6)]},{chord:'V',lyric:'每一步，都有回音',melody:[n(5),n(7),n(2,1,1),n(7)]}]},
{name:'间奏',type:'instrumental',bars:[{chord:'ii',melody:[n(2),n(4),n(6),n(1,1,1)]},{chord:'V',melody:[n(7),n(5),n(2),n(7)]}]},
{name:'演唱 B',type:'vocal',bars:[{chord:'IV',lyric:'风吹来，新的旋律',melody:[n(6),n(1,1,1),n(6),n(4)]},{chord:'V',lyric:'听见你，也听见自己',melody:[n(5),n(7),n(2,1,1),n(5)]}]},
{name:'尾奏',type:'instrumental',bars:[{chord:'V',melody:[n(7),n(5),n(2),n(7)]},{chord:'I',melody:[n(1,4)]}]}]};
let performanceScore=originalScore,performanceEvents=[],performanceTimers=[],performancePlaying=false,performanceBar=0,performanceRun=0;
const functionalChords={I:{degree:1,type:'major'},ii:{degree:2,type:'minor'},iii:{degree:3,type:'minor'},IV:{degree:4,type:'major'},V:{degree:5,type:'major'},vi:{degree:6,type:'minor'},'vii°':{degree:7,type:'dim'}};
songPanel.innerHTML=intro('06','看着谱，让音乐真正走起来。','旋律简谱与和弦级数并排阅读；听到哪里，琴键与小节就亮到哪里。')+`<section class="reading-card performance-intro"><div class="section-art art-chord" aria-hidden="true"></div><h2>前奏弹旋律，演唱留出声音的位置。</h2><p>这里展示一种入门弹唱编配：演唱段以和弦伴奏为主，前奏、间奏、尾奏加上旋律。实际歌曲可以有不同编配，不是所有器乐段都只弹单音。</p><p>先用原创短曲跑通阅读与演奏。要演示《晴天》，可导入你持有使用权限的对应谱子；本站未内置该曲旋律、歌词或录音。</p></section><section class="reading-card performance-player"><div class="performance-controls"><label>曲目<select id="performanceSong"><option value="original">微光归途 · 原创示范</option><option value="import">导入我的曲谱…</option></select></label><label>调性<select id="performanceRoot">${roots.map((r,i)=>`<option value="${i}">${r[0]} 大调</option>`).join('')}</select></label><label>速度 <input id="performanceTempo" type="number" min="40" max="160" value="80"> BPM</label><label class="guide-toggle"><input id="performanceGuide" type="checkbox"> 演唱段加旋律提示音</label></div><div class="performance-transport"><button class="primary" id="performancePlay">▶ 从当前小节播放</button><button id="performanceStop" disabled>■ 停止</button><button id="performanceReset">↤ 回到开头</button><span id="performanceState" role="status">准备就绪 · 点击任意小节可选择播放起点</span></div><div class="performance-now"><div><small>当前段落</small><strong id="performanceSection">前奏</strong></div><div><small>和弦级数 → 实际和弦</small><strong id="performanceChord">I → C</strong></div><div><small>当前演奏</small><strong id="performanceMode">旋律 + 和弦伴奏</strong></div></div><p class="voice-notice">当前为合成钢琴演示，未配录制人声。勾选提示音可听演唱段旋律。</p><div class="performance-keyboards" id="performanceKeys"></div><div class="performance-legend"><span>● 暖色：旋律音</span><span>● 主题色：和弦伴奏</span><span>数字上方 · 表示高八度，下方 · 表示低八度；0 表示休止</span></div><div id="performanceScore"></div></section><section class="reading-card" id="scoreImport" hidden><h2>导入旋律简谱＋和弦级数</h2><p>目前接收结构化 JSON 曲谱，尚不支持识别图片或 PDF。先点击“载入格式示例”，按示例填入你所用的谱，再点导入。曲谱仅在当前页面会话中使用。</p><p>degree 为简谱 1～7（0 为休止），octave 为相对中央音区的八度（−1、0、1），beats 为时值；每小节合计 4 拍。和弦级数支持 I、ii、iii、IV、V、vi、vii°。</p><div class="import-actions"><button id="scoreTemplate">载入格式示例</button><label>或选择 JSON 文件 <input id="scoreFile" type="file" accept=".json,application/json"></label></div><textarea id="scoreData" rows="10" aria-label="曲谱 JSON" placeholder="在此粘贴曲谱 JSON…"></textarea><button class="primary" id="scoreApply">导入并预览</button><p id="scoreImportStatus" role="status"></p></section>`;
function scoreEscape(value){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function perfRoot(){return roots[+$('#performanceRoot').value]}
function perfMelody(note){return 60+perfRoot()[1]+majorSteps[note.degree-1]+note.octave*12}
function perfChord(bar){const c=functionalChords[bar.chord],root=perfRoot(),delta=majorSteps[c.degree-1],pc=(root[1]+delta)%12,letter=letters[(letters.indexOf(root[0][0])+c.degree-1)%7],d=((pc-natural[letter]+18)%12)-6;const name=letter+({[-2]:'𝄫',[-1]:'♭',0:'',1:'♯',2:'𝄪'}[d])+(c.type==='minor'?'m':c.type==='dim'?'dim':'');const base=48+root[1]+delta;return {name,notes:[0,c.type==='major'?4:3,c.type==='dim'?6:7].map(n=>base+n)}}
function flattenScore(){return performanceScore.sections.flatMap((section,sectionIndex)=>section.bars.map(bar=>({...bar,section:section.name,type:section.type,sectionIndex})))}
function perfKeys(){const root=perfRoot()[1];$('#performanceKeys').innerHTML=[['伴奏音区',36+root,37],['旋律音区',48+root,37]].map(([label,start,length])=>{const notes=Array.from({length},(_,i)=>start+i),whites=notes.filter(m=>![1,3,6,8,10].includes(m%12));let count=0;return `<div><small>${label}</small><div class="performance-keyscroll"><div class="performance-keyrow">${notes.map(m=>{const black=[1,3,6,8,10].includes(m%12),pos=count;if(!black)count++;return `<span class="performance-key ${black?'black':'white'}" data-perf-midi="${m}" style="${black?'left:calc('+pos/whites.length*100+'% - 1.6%)':'width:'+100/whites.length+'%'}">${roots.find(r=>r[1]===m%12)[0]}</span>`}).join('')}</div></div></div>`}).join('')}
function perfPaint(){const active=[...voices].filter(([id])=>id.startsWith('performance-')).map(([id,v])=>({midi:(octave+1)*12+v.offset,melody:id.includes('melody')}));$$('[data-perf-midi]').forEach(k=>{k.classList.toggle('active-chord',active.some(v=>!v.melody&&v.midi===+k.dataset.perfMidi));k.classList.toggle('active-melody',active.some(v=>v.melody&&v.midi===+k.dataset.perfMidi))})}
const prePerformanceVisual=liveVisual;liveVisual=function(){prePerformanceVisual();perfPaint()};
function perfBarUI(index){const bars=flattenScore(),bar=bars[index];if(!bar)return;performanceBar=index;$$('[data-perf-bar]').forEach(b=>{b.classList.toggle('current',+b.dataset.perfBar===index);b.setAttribute('aria-pressed',+b.dataset.perfBar===index)});$('#performanceSection').textContent=bar.section;$('#performanceChord').textContent=bar.chord+' → '+perfChord(bar).name;$('#performanceMode').textContent=bar.type==='vocal'?($('#performanceGuide').checked?'伴奏 + 旋律提示音':'和弦伴奏 · 留给演唱'):'旋律 + 和弦伴奏';}
function renderPerformance(){let index=0;$('#performanceScore').innerHTML=`<div class="score-title"><h2></h2><p></p></div>`+performanceScore.sections.map(section=>`<section class="score-section"><h3>${scoreEscape(section.name)} <small>${section.type==='vocal'?'演唱段 · 和弦为主':'器乐段 · 旋律与和弦'}</small></h3><div class="score-bars">${section.bars.map(bar=>{const i=index++;return `<button data-perf-bar="${i}" class="score-bar"><small>第 ${i+1} 小节</small><strong>${bar.chord} <span>→ ${perfChord(bar).name}</span></strong><div class="numbered-notes">${bar.melody.map((note,j)=>`<span data-perf-note="${i}-${j}" class="${note.octave>0?'upper':note.octave<0?'lower':''}">${note.degree}${note.beats>1?'<small>'+('—'.repeat(Math.min(3,Math.ceil(note.beats)-1)))+'</small>':''}</span>`).join('')}</div><p class="score-lyric"></p></button>`}).join('')}</div></section>`).join('');$('#performanceScore .score-title h2').textContent=performanceScore.title;$('#performanceScore .score-title p').textContent=performanceScore.credit;const bars=flattenScore();$$('.score-lyric').forEach((p,i)=>p.textContent=bars[i].lyric||'器乐演奏');perfKeys();perfBarUI(Math.min(performanceBar,bars.length-1))}
function stopPerformance(){performanceRun++;performancePlaying=false;performanceTimers.forEach(clearTimeout);performanceTimers=[];[...held].filter(id=>id.startsWith('performance-')).forEach(noteOff);$$('[data-perf-note]').forEach(n=>n.classList.remove('playing'));$('#performancePlay').disabled=false;$('#performanceStop').disabled=true;$('#performanceState').textContent='已停止 · 可选择小节重新播放';}
function perfSchedule(fn,ms){performanceTimers.push(setTimeout(fn,ms))}
$('#performancePlay').onclick=async()=>{if(performancePlaying)return;stopPerformance();stopSong();const run=performanceRun;await audio();if(run!==performanceRun)return;performancePlaying=true;$('#performancePlay').disabled=true;$('#performanceStop').disabled=false;const beat=60000/Math.max(40,Math.min(160,+$('#performanceTempo').value||80)),bars=flattenScore(),from=performanceBar;let at=0;bars.slice(from).forEach((bar,k)=>{const index=from+k,start=at;perfSchedule(()=>{perfBarUI(index);$('#performanceState').textContent=`播放中 · 第 ${index+1} / ${bars.length} 小节`;perfChord(bar).notes.forEach((m,j)=>noteOn(`performance-chord-${index}-${j}`,m-(octave+1)*12))},start);perfSchedule(()=>perfChord(bar).notes.forEach((_,j)=>noteOff(`performance-chord-${index}-${j}`)),start+beat*3.9);let offset=0;bar.melody.forEach((note,j)=>{const id=`performance-melody-${index}-${j}`,moment=start+offset*beat;perfSchedule(()=>{const el=$(`[data-perf-note="${index}-${j}"]`);el?.classList.add('playing');if(note.degree&&(bar.type!=='vocal'||$('#performanceGuide').checked))noteOn(id,perfMelody(note)-(octave+1)*12)},moment);perfSchedule(()=>{noteOff(id);$(`[data-perf-note="${index}-${j}"]`)?.classList.remove('playing')},moment+note.beats*beat*.9);offset+=note.beats});at+=4*beat});perfSchedule(()=>{stopPerformance();$('#performanceState').textContent='播放完成 · 可回到开头再听一次'},at+50)};
$('#performanceStop').onclick=stopPerformance;$('#performanceReset').onclick=()=>{stopPerformance();perfBarUI(0)};$('#performanceScore').onclick=e=>{const b=e.target.closest('[data-perf-bar]');if(b){stopPerformance();perfBarUI(+b.dataset.perfBar)}};['#performanceRoot','#performanceTempo'].forEach(s=>$(s).onchange=()=>{stopPerformance();renderPerformance()});$('#performanceGuide').onchange=()=>{if(!$('#performanceGuide').checked)[...held].filter(id=>id.startsWith('performance-melody-')).forEach(noteOff);perfBarUI(performanceBar)};
const stopOnTopic=switchTopic;switchTopic=function(i,h=true){if(i!==6)stopPerformance();stopOnTopic(i,h)};window.addEventListener('blur',stopPerformance);document.addEventListener('visibilitychange',()=>{if(document.hidden)stopPerformance()});
$('#performanceSong').onchange=e=>{stopPerformance();if(e.target.value==='import'){$('#scoreImport').hidden=false;$('#scoreImport').scrollIntoView({behavior:'smooth'})}else{performanceScore=originalScore;performanceBar=0;$('#scoreImport').hidden=true;renderPerformance()}};$('#scoreTemplate').onclick=()=>{$('#scoreData').value=JSON.stringify(originalScore,null,2)};
function validateScore(s){if(!s||typeof s.title!=='string'||!s.title.trim()||s.title.length>100)throw Error('曲目标题需为 1～100 个字符');if(!Array.isArray(s.sections)||!s.sections.length||s.sections.length>16)throw Error('需要 1～16 个段落');let count=0;const clean={title:s.title,credit:typeof s.credit==='string'?s.credit.slice(0,200):'用户导入曲谱',sections:s.sections.map(section=>{if(!['vocal','instrumental'].includes(section.type)||!Array.isArray(section.bars)||!section.bars.length||section.bars.length>64)throw Error('段落需有 type（vocal/instrumental）及 1～64 个小节');return {name:String(section.name||'未命名段落').slice(0,30),type:section.type,bars:section.bars.map(bar=>{count++;if(!functionalChords[bar.chord])throw Error('和弦级数须为 I、ii、iii、IV、V、vi、vii°');if(!Array.isArray(bar.melody)||!bar.melody.length||bar.melody.length>32)throw Error('每小节需要 1～32 个旋律音');const melody=bar.melody.map(note=>{if(!Number.isInteger(note.degree)||note.degree<0||note.degree>7||![-1,0,1].includes(note.octave)||typeof note.beats!=='number'||!Number.isFinite(note.beats)||note.beats<=0||note.beats>4)throw Error('音符 degree 为 0～7，octave 为 -1/0/1，beats 大于 0 且不超过 4');return {degree:note.degree,octave:note.octave,beats:note.beats}});if(Math.abs(melody.reduce((a,n)=>a+n.beats,0)-4)>.001)throw Error('每小节旋律时值必须合计 4 拍');return {chord:bar.chord,lyric:typeof bar.lyric==='string'?bar.lyric.slice(0,100):'',melody}})}})};if(count>128)throw Error('曲谱最多 128 小节');return clean}
$('#scoreFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>200000){$('#scoreImportStatus').textContent='文件请控制在 200 KB 以内';return}$('#scoreData').value=await f.text()};$('#scoreApply').onclick=()=>{try{const score=validateScore(JSON.parse($('#scoreData').value));stopPerformance();performanceScore=score;performanceBar=0;renderPerformance();$('#scoreImportStatus').textContent='导入成功，可在上方播放。';$('#performanceSong').options[1].textContent='当前导入：'+score.title;$('.performance-player').scrollIntoView({behavior:'smooth'})}catch(e){$('#scoreImportStatus').textContent='无法导入：'+e.message}};
renderPerformance();if(location.hash==='#topic-6')switchTopic(6,false);
